package com.nanless.paperdigest.zotero.webdav
import com.nanless.paperdigest.secret.SecretStore
import kotlinx.coroutines.runBlocking
import okhttp3.Request
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.io.IOException
import java.nio.file.Files
import java.util.UUID

class ZoteroDavDurabilityTest {
    private fun root()=Files.createTempDirectory("dav-directory-sync-").toFile().canonicalFile
    private fun target()=ZoteroDavTarget.native("users","123","https://dav.example.org/dav/","synthetic",UUID.randomUUID().toString(),UUID.randomUUID().toString())
    private fun rejects(body:()->Unit):Exception{try{body()}catch(e:Exception){return e};throw AssertionError("Expected failure")}
    @Test fun actualDefaultDirectoryChannelForceWorksAndRootAndChildEntriesAreSynced(){val base=root();try{val observed=mutableListOf<File>();val files=DavFiles(File(base,"control")){dir->DavFiles.syncDirectory(dir);observed+=dir};assertTrue(observed.contains(base)&&observed.contains(files.root));val child=files.create(UUID.randomUUID().toString());assertTrue(observed.contains(child));files.createBytes(files.named(child,"original.bin"),"synthetic".toByteArray());assertEquals(child,observed.last());assertEquals("synthetic",File(child,"original.bin").readText())}finally{base.deleteRecursively()}}
    @Test fun journalWriteIntentReturnsOnlyAfterActualRenameDirectorySync(){val base=root();try{var sawPlanned=false;var enable=false;val files=DavFiles(File(base,"control")){dir->DavFiles.syncDirectory(dir);val path=File(dir,"journal.json");if(enable&&path.isFile&&JSONObject(path.readText()).optString("phase")=="zip-put-planned")sawPlanned=true};val id=UUID.randomUUID().toString();val journal=DavJournal.create(files,id,files.create(id),JSONObject());enable=true;journal.update{it.put("phase","zip-put-planned")};assertTrue(sawPlanned);assertEquals("zip-put-planned",journal.read().getString("phase"))}finally{base.deleteRecursively()}}
    @Test fun prepareDirectorySyncFailurePreservesActualFilesAndReturnsNoCapability()=runBlocking{val base=root();try{val file=File(base,"original").apply{writeText("synthetic原材料")};val bytes=file.readBytes();var keyReads=0;var requests=0;val keys=object:SecretStore{override fun load(scope:String):String{keyReads++;return "synthetic"};override fun save(scope:String,secret:String)=error("not used");override fun remove(scope:String)=error("not used")};val wire=object:DavWireTransport{override suspend fun exchange(request:Request,limit:Long,reply:DavReplyFile?,check:()->Unit):DavWireReply{requests++;error("No dispatch allowed")}};val backend=ZoteroDavBackend(File(base,"control"),keys,wire,available={base.usableSpace},clock=System::currentTimeMillis,directorySync={dir->DavFiles.syncDirectory(dir);if(File(dir,"journal.json").isFile)throw IOException("synthetic sync failure")});val t=target();val lease=ZoteroDavLease.native(t,UUID.randomUUID().toString(),UUID.randomUUID().toString(),1){true};val material=ZoteroDavAttachment.native("ABCD2345","BCDE3456","pdf","synthetic-paper","b".repeat(64),"Synthetic","application/pdf",file,davHash(bytes));var failed=false;try{backend.prepare(material,lease)}catch(e:ZoteroDavFailure){failed=true;assertEquals("storage",e.code)};assertTrue(failed);assertEquals(0,keyReads);assertEquals(0,requests);assertArrayEquals(bytes,file.readBytes());val op=File(base,"control").listFiles()!!.single{it.isDirectory};assertTrue(File(op,"journal.json").isFile);assertArrayEquals(bytes,File(op,"original.bin").readBytes())}finally{base.deleteRecursively()}}
    @Test fun postRenameDirectorySyncFailureDoesNotAdvanceOldInMemoryJournalOrEraseIntent(){val base=root();try{var fail=false;val files=DavFiles(File(base,"control")){dir->DavFiles.syncDirectory(dir);if(fail&&File(dir,"journal.json").isFile)throw IOException("synthetic")};val id=UUID.randomUUID().toString();val j=DavJournal.create(files,id,files.create(id),JSONObject());fail=true;rejects{j.update{it.put("phase","zip-put-planned")}};val actual=File(j.dir,"journal.json").readBytes();assertEquals("zip-put-planned",JSONObject(String(actual)).getString("phase"));assertEquals("journalChanged",(rejects{j.read()}as ZoteroDavFailure).code);fail=false;val reopened=DavJournal.reopen(files,id);assertEquals("zip-put-planned",reopened.read().getString("phase"));assertArrayEquals(actual,File(j.dir,"journal.json").readBytes())}finally{base.deleteRecursively()}}
    @Test fun failedBackoffDirectorySyncKeepsActualCooldownForExplicitColdReopen(){val base=root();try{var fail=false;val files=DavFiles(File(base,"control")){dir->DavFiles.syncDirectory(dir);if(fail&&File(dir,"backoff.json").isFile)throw IOException("synthetic")};val pacing=DavBackoff(files){1000};fail=true;rejects{pacing.record(true,429,emptyMap())};val actual=File(files.root,"backoff.json").readBytes();val cold=DavBackoff(DavFiles(files.root)){1000};assertEquals("backoff",(rejects{cold.before(true)}as ZoteroDavFailure).code);assertArrayEquals(actual,File(files.root,"backoff.json").readBytes())}finally{base.deleteRecursively()}}
    @Test fun directoryReplacementDuringSyncIsRejectedWithoutDeletingEitherDirectory(){val base=root();try{var swap=false;val files=DavFiles(File(base,"control")){dir->DavFiles.syncDirectory(dir);if(swap&&dir.parentFile==File(base,"control")){assertTrue(dir.renameTo(File(dir.parentFile,"retained-old")));assertTrue(dir.mkdir());File(dir,"unknown.bin").writeText("unknown")}};val id=UUID.randomUUID().toString();val dir=files.create(id);swap=true;assertEquals("path",(rejects{files.createBytes(files.named(dir,"original.bin"),byteArrayOf(1))}as ZoteroDavFailure).code);assertTrue(File(files.root,"retained-old/original.bin").isFile);assertEquals("unknown",File(dir,"unknown.bin").readText())}finally{base.deleteRecursively()}}
}
